exercises.solution:
import math

def ekspektasi_kontinu(f, a, b, n=100000):
    h = (b - a) / n
    total = 0.0
    for i in range(n):
        x = a + (i + 0.5) * h
        total += x * f(x)
    return round(total * h, 4)

